#!/usr/bin/env python3
"""K4 cross-review oracle: check kernel/src/trustselftest.rs constants and the
kernel's SHA-2/Ed25519 implementation against sources that share no code with it.

Oracles used here (none of them is the kernel):
  * tests/fixtures/ed25519-openssl.json, generated by the committed
    tests/fixtures/gen_ed25519_openssl.py through the `cryptography` package
    (OpenSSL).  The fixture is re-generated into a temp dir and byte-compared.
  * RFC 8032 section 7.1, TEST 1/2/3 vectors, verified with the local `openssl`
    CLI (OpenSSL 3.x) so a mistyped vector fails instead of passing silently.
  * hashlib (FIPS 180-4 test messages: "", "abc", the 448-bit and 896-bit
    messages) for the SHA-2 digests.
  * The kernel implementation itself is exercised on the host through a scratch
    crate built from `git show HEAD:kernel/src/trust.rs`, so each digest and
    verification result is compared to an expected value computed above.

Run from the repository root:
    python docs/reviews/k4-freebuff-vectors.py
"""

import hashlib
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
FIXTURE = ROOT / "tests" / "fixtures" / "ed25519-openssl.json"
SELFTEST = ROOT / "kernel" / "src" / "trustselftest.rs"
# Optional argv[1] lets the same harness score a planted copy of trust.rs, which
# is how each plant is shown to change behaviour before the boot exit code is read.
TRUST = Path(sys.argv[1]) if len(sys.argv) > 1 else ROOT / "kernel" / "src" / "trust.rs"

# RFC 8032 section 7.1, TEST 1-3 (public document).  Every one of these is
# checked with openssl before it is used, so a transcription error is visible.
RFC_8032_7_1 = [
    (
        "TEST 1 (empty message)",
        "9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60",
        "d75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a",
        "",
        "e5564300c360ac729086e2cc806e828a84877f1eb8e5d974d873e065224901555f"
        "b8821590a33bacc61e39701cf9b46bd25bf5f0595bbe24655141438e7a100b",
    ),
    (
        "TEST 2 (one-byte message)",
        "4ccd089b28ff96da9db6c346ec114e0f5b8a319f35aba624da8cf6ed4fb8a6fb",
        "3d4017c3e843895a92b70aa74d1b7ebc9c982ccf2ec4968cc0cd55f12af4660c",
        "72",
        "92a009a9f0d4cab8720e820b5f642540a2b27b5416503f8fb3762223ebdb69da"
        "085ac1e43e15996e458f3613d0f11d8c387b2eaeb4302aeeb00d291612bb0c00",
    ),
    (
        "TEST 3 (two-byte message)",
        "c5aa8df43f9f837bedb7442f31dcb7b166d38535076f094b85ce3a2e0b4458f7",
        "fc51cd8e6218a1a38da47ed00230f0580816ed13ba3303ac5deb911548908025",
        "af82",
        "6291d657deec24024827e69c3abe01a30ce548a284743a445e3680d7db5ac3ac"
        "18ff9b538d16f290ae67f760984dc6594a7c15e9716ed28dc027beceea1ec40a",
    ),
]

# FIPS 180-4 example messages (NIST CAVP / SP 800-232 examples).
FIPS_MESSAGES = {
    "empty": b"",
    "abc": b"abc",
    "448-bit": b"abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq",
    "896-bit": bytes.fromhex(
        "6162636465666768696a6b6c6d6e6f707172737475767778797a"
        "3031323334353637383930313233343536373839303132333435"
        "3637383930313233343536373839303132333435363738393031"
        "3233343536373839"
    ),
}

results = []


def record(name, ok, detail=""):
    results.append((name, ok, detail))
    print(f"{'PASS' if ok else 'FAIL'}  {name}" + (f"  [{detail}]" if detail else ""))
    return ok


# ---------------------------------------------------------------- Rust literal


def rust_byte_array(source, name):
    """Parse `const|let NAME: [u8; N] = [0x.., ...];` out of a Rust source file."""
    match = re.search(
        rf"(?:const|let) {name}: \[u8; (\d+)\] = \[(.*?)\];", source, re.S
    )
    if not match:
        raise SystemExit(f"could not find {name} in {SELFTEST.name}")
    declared = int(match.group(1))
    body = match.group(2)
    values = [int(v, 16) for v in re.findall(r"0x([0-9a-fA-F]{2})", body)]
    if len(values) != declared:
        raise SystemExit(f"{name}: declared {declared} bytes, parsed {len(values)}")
    return bytes(values)


def rust_byte_string(source, name):
    """Parse `const NAME: &[u8] = b"...";` with Rust escapes into bytes."""
    match = re.search(rf'const {name}: &\[u8\] = b"(.*?)";', source, re.S)
    if not match:
        raise SystemExit(f"could not find {name}")
    body = match.group(1)
    out = bytearray()
    i = 0
    while i < len(body):
        ch = body[i]
        if ch != "\\":
            out.extend(ch.encode("utf-8"))
            i += 1
            continue
        esc = body[i + 1]
        if esc == "n":
            out.append(0x0A)
            i += 2
        elif esc == "r":
            out.append(0x0D)
            i += 2
        elif esc == "t":
            out.append(0x09)
            i += 2
        elif esc == "0":
            out.append(0x00)
            i += 2
        elif esc == "\\":
            out.append(0x5C)
            i += 2
        elif esc == '"':
            out.append(0x22)
            i += 2
        elif esc == "x":
            out.append(int(body[i + 2:i + 4], 16))
            i += 4
        else:
            raise SystemExit(f"{name}: unsupported escape \\{esc}")
    return bytes(out)


def rust_u8_tables(source):
    """All `const|let X: [u8; N] = [...]` tables in the selftest, by name."""
    names = re.findall(r"(?:const|let) ([A-Za-z0-9_]+): \[u8; \d+\] = \[", source)
    return {name: rust_byte_array(source, name) for name in names}


# ---------------------------------------------------------------- openssl helpers


def openssl_ed25519_verify(pubkey, message, signature):
    """Independent verification through OpenSSL. True if accepted.

    `cryptography` (OpenSSL bindings) is used first because the openssl CLI's
    `pkeyutl -rawin` refuses a zero-byte input file (TEST 1 is the empty
    message).  The CLI is also run for non-empty messages as a second oracle.
    """
    try:
        from cryptography.exceptions import InvalidSignature
        from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey

        key = Ed25519PublicKey.from_public_bytes(pubkey)
        try:
            key.verify(signature, message)
            accepted = True
        except InvalidSignature:
            accepted = False
    except ImportError:
        accepted = None

    spki = bytes.fromhex("302a300506032b6570032100") + pubkey
    pem = (
        "-----BEGIN PUBLIC KEY-----\n"
        + "\n".join(
            __import__("base64").b64encode(spki).decode()[i:i + 64]
            for i in range(0, len(__import__("base64").b64encode(spki).decode()), 64)
        )
        + "\n-----END PUBLIC KEY-----\n"
    )
    with tempfile.TemporaryDirectory() as tmp:
        tmp = Path(tmp)
        (tmp / "pub.pem").write_text(pem)
        (tmp / "msg.bin").write_bytes(message)
        (tmp / "sig.bin").write_bytes(signature)
        proc = subprocess.run(
            [
                "openssl", "pkeyutl", "-verify", "-pubin", "-inkey", str(tmp / "pub.pem"),
                "-rawin", "-in", str(tmp / "msg.bin"), "-sigfile", str(tmp / "sig.bin"),
            ],
            capture_output=True,
            text=True,
        )
    if message:
        cli = proc.returncode == 0
        if accepted is not None and cli != accepted:
            raise SystemExit("openssl CLI and cryptography disagree on a vector")
        return cli
    # Empty message: the CLI cannot allocate a zero-byte rawin buffer; the
    # openssl-backed `cryptography` result stands alone (rc 1 is expected).
    if accepted is None:
        raise SystemExit("empty-message vector needs the cryptography package")
    return accepted


def main():
    fixture = json.loads(FIXTURE.read_text(encoding="utf-8"))
    selftest_src = SELFTEST.read_text(encoding="utf-8")
    trust_src = TRUST.read_text(encoding="utf-8")

    print("== 1. Fixture is reproducible from the committed generator ==")
    with tempfile.TemporaryDirectory() as tmp:
        tmp = Path(tmp)
        shutil.copy(FIXTURE.parent / "gen_ed25519_openssl.py", tmp / "gen.py")
        proc = subprocess.run(
            [sys.executable, str(tmp / "gen.py")], capture_output=True, text=True
        )
        regenerated = tmp / "ed25519-openssl.json"
        if proc.returncode != 0 or not regenerated.exists():
            record("fixture regenerates with the committed generator", False,
                   (proc.stdout + proc.stderr).strip()[:200])
        else:
            same = regenerated.read_bytes() == FIXTURE.read_bytes()
            head = hashlib.sha256(FIXTURE.read_bytes()).hexdigest()
            record("fixture regenerates byte-identically", same,
                   f"sha256={head[:16]}... local openssl/cryptography")

    print("\n== 2. Selftest constants vs the fixture (byte for byte) ==")
    tables = rust_u8_tables(selftest_src)
    canonical = rust_byte_string(selftest_src, "CANONICAL_MANIFEST_JSON")
    manifest = fixture["manifest"]
    v0 = fixture["vectors"][0]

    record("vectors[0].message is empty (SIG_0 covers b\"\")",
           v0["message"] == "", f"message bytes={len(v0['message']) // 2}")
    record("PUBKEY_0 == fixture vectors[0].public",
           tables.get("PUBKEY_0") == bytes.fromhex(v0["public"]),
           f"kernel {tables.get('PUBKEY_0', b'!').hex()[:16]}... fixture {v0['public'][:16]}...")
    record("SIG_0 == fixture vectors[0].signature",
           tables.get("SIG_0") == bytes.fromhex(v0["signature"]))
    signing_input = bytes.fromhex(manifest["signing_input"])
    record("CANONICAL_MANIFEST_JSON == fixture signing_input minus the 17-byte context",
           signing_input.startswith(b"NOVA-MANIFEST-v1\n")
           and canonical == signing_input[len(b"NOVA-MANIFEST-v1\n"):],
           f"kernel {len(canonical)} bytes, fixture {len(signing_input) - 17} bytes")
    record("manifest public key == PUBKEY_0",
           bytes.fromhex(manifest["public"]) == tables["PUBKEY_0"])

    # SHA-2 constants in the selftest
    sha_constants = {
        "want_empty_sha256": hashlib.sha256(b"").digest(),
        "want_fox_sha256": hashlib.sha256(
            b"The quick brown fox jumps over the lazy dog").digest(),
        "want_empty_sha512": hashlib.sha512(b"").digest(),
    }
    for name, expected in sha_constants.items():
        record(f"{name} == hashlib (FIPS 180-4)", tables.get(name) == expected,
               f"kernel {tables.get(name, b'!')[:8].hex()}... hashlib {expected[:8].hex()}...")

    print("\n== 3. Manifest signature: openssl over the fixture signing input ==")
    sig = tables.get("MANIFEST_SIG")
    ok = openssl_ed25519_verify(bytes.fromhex(manifest["public"]), signing_input, sig)
    record("MANIFEST_SIG verifies with openssl over fixture signing_input", ok,
           f"kernel sig {sig[:8].hex()}...")
    # Negative control: the same signature must fail over one changed byte.
    tampered = bytearray(signing_input)
    tampered[-1] ^= 0x01
    record("openssl rejects MANIFEST_SIG over a one-byte-changed input",
           not openssl_ed25519_verify(bytes.fromhex(manifest["public"]), bytes(tampered), sig))

    print("\n== 4. RFC 8032 section 7.1 TEST 1-3, verified by openssl ==")
    for label, _sk, pub, msg_hex, sig_hex in RFC_8032_7_1:
        pub_b, msg_b, sig_b = bytes.fromhex(pub), bytes.fromhex(msg_hex), bytes.fromhex(sig_hex)
        record(f"{label}: openssl accepts RFC vector", openssl_ed25519_verify(pub_b, msg_b, sig_b))
        flipped = bytearray(msg_b + b"\x00") if not msg_b else bytearray(msg_b)
        flipped[0] ^= 0x01
        record(f"{label}: openssl rejects changed message",
               not openssl_ed25519_verify(pub_b, bytes(flipped), sig_b))

    print("\n== 5. Kernel implementation on the host (scratch crate) ==")
    host_ok = run_host_harness(trust_src, fixture, tables)

    failed = [name for name, ok, _ in results if not ok]
    print(f"\nSUMMARY: {len(results) - len(failed)} passed, {len(failed)} failed, "
          f"{len(results)} checks")
    if failed:
        for name in failed:
            print(f"  FAILED: {name}")
        return 1
    return 0 if host_ok else 1


def run_host_harness(trust_src, fixture, tables):
    """Compile kernel/src/trust.rs in a scratch host crate and run oracle vectors."""
    v0 = fixture["vectors"][0]
    vectors = []
    for label, _sk, pub, msg_hex, sig_hex in RFC_8032_7_1:
        vectors.append((label, bytes.fromhex(pub), bytes.fromhex(msg_hex), bytes.fromhex(sig_hex)))

    negatives = []
    for neg in v0["negatives"]:
        if neg["openssl_accepts"]:
            continue  # fixture only lists rejects; keep any that are rejects
        negatives.append((neg["kind"], bytes.fromhex(neg["public"]),
                          bytes.fromhex(neg["message"]), bytes.fromhex(neg["signature"])))
    # S + L (malleable encoding) must be listed as rejected by openssl.
    record("fixture lists 'S + L (malleable encoding)' as openssl-rejected",
           any(n[0].startswith("S + L") for n in negatives))
    record("fixture lists 'R with y >= p (non-canonical)' as openssl-rejected",
           any(n[0].startswith("R with y >= p") for n in negatives))

    hashes = []
    for label, msg in FIPS_MESSAGES.items():
        hashes.append((label, msg, hashlib.sha256(msg).digest(), hashlib.sha512(msg).digest()))

    def rust_bytes(b):
        return "[" + ", ".join(f"0x{x:02x}" for x in b) + "]"

    def rust_str(b):
        return json.dumps(b.decode("utf-8"))

    lines = []
    lines.append("fn main() {")
    lines.append("    let mut pass = 0u32; let mut fail = 0u32;")
    lines.append("    macro_rules! ck { ($ok:expr, $name:expr) => {"
                 " if $ok { pass += 1; println!(\"PASS  {}\", $name); }"
                 " else { fail += 1; println!(\"FAIL  {}\", $name); } } }")
    for label, msg, want256, want512 in hashes:
        lines.append(f"    let m = {rust_bytes(msg)};")
        lines.append(f"    ck!(crate::trust::sha256(&m) == {rust_bytes(want256)}, "
                     f"\"sha256 {label} matches hashlib\");")
        lines.append(f"    ck!(crate::trust::sha512(&m) == {rust_bytes(want512)}, "
                     f"\"sha512 {label} matches hashlib\");")
    for label, pub, msg, sig in vectors:
        lines.append(
            f"    ck!(crate::trust::ed25519_verify(&{rust_bytes(pub)}, &{rust_bytes(msg)}, "
            f"&{rust_bytes(sig)}), \"ed25519 {label} valid signature accepted\");")
    for kind, pub, msg, sig in negatives:
        name = kind.replace('"', "'")
        lines.append(
            f"    ck!(!crate::trust::ed25519_verify(&{rust_bytes(pub)}, &{rust_bytes(msg)}, "
            f"&{rust_bytes(sig)}), \"ed25519 negative rejected: {name}\");")
    # All-zero public key and all-zero signature must be rejected.
    lines.append("    let zero32 = [0u8; 32]; let zero64 = [0u8; 64];")
    lines.append("    ck!(!crate::trust::ed25519_verify(&zero32, b\"attack\", &zero64), "
                 "\"all-zero public key + all-zero signature rejected\");")
    # Non-canonical S for an otherwise valid RFC TEST 1 signature.
    _label, pub, msg, sig = vectors[0]
    s = int.from_bytes(sig[32:], "little")
    L = 2 ** 252 + 27742317777372353535851937790883648493
    s_plus_l = (s + L).to_bytes(32, "little")
    lines.append(
        f"    ck!(!crate::trust::ed25519_verify(&{rust_bytes(pub)}, &{rust_bytes(msg)}, "
        f"&{rust_bytes(sig[:32] + s_plus_l)}), \"RFC TEST 1 with S+L rejected\");")
    lines.append("    println!(\"HOST SUMMARY: {} passed, {} failed\", pass, fail);")
    lines.append("    std::process::exit(if fail == 0 { 0 } else { 1 });")
    lines.append("}")

    with tempfile.TemporaryDirectory() as tmp:
        tmp = Path(tmp)
        (tmp / "src").mkdir()
        (tmp / "Cargo.toml").write_text(
            "[package]\nname = \"k4host\"\nversion = \"0.0.0\"\nedition = \"2021\"\n",
            encoding="utf-8")
        (tmp / "src" / "trust.rs").write_text(trust_src, encoding="utf-8")
        header = (
            "#[allow(dead_code)]\n"
            "mod cap {\n"
            "    #[derive(Clone, Copy)]\n"
            "    pub struct CapSet;\n"
            "}\n"
            "#[allow(dead_code)]\n"
            "mod trust;\n"
        )
        (tmp / "src" / "main.rs").write_text(
            header + "\n".join(lines) + "\n", encoding="utf-8")
        # The host linker on this Windows checkout is broken (`link: missing
        # operand after '\377\376'`, the same failure B4/B5 hit), so the harness
        # is compiled for wasm32-wasip1 and run under node's WASI.  The crate is
        # std-only, so the target changes nothing about the code under test.
        target_dir = ROOT / "build" / "k4-host-target"
        build = subprocess.run(
            ["cargo", "build", "--quiet", "--target", "wasm32-wasip1",
             "--manifest-path", str(tmp / "Cargo.toml")],
            capture_output=True, text=True,
            env={**os.environ, "CARGO_TARGET_DIR": str(target_dir)},
        )
        wasm = target_dir / "wasm32-wasip1" / "debug" / "k4host.wasm"
        if build.returncode != 0 or not wasm.exists():
            print(build.stdout.strip())
            print(build.stderr.strip()[-2000:])
            return False
        runner = tmp / "run.mjs"
        runner.write_text(
            "import { WASI } from 'node:wasi';\n"
            "import { argv } from 'node:process';\n"
            "import { readFileSync } from 'node:fs';\n"
            "const wasi = new WASI({ version: 'preview1', args: argv.slice(2), "
            "env: {}, returnOnExit: true });\n"
            "const mod = await WebAssembly.compile(readFileSync(argv[2]));\n"
            "const inst = await WebAssembly.instantiate(mod, wasi.getImportObject());\n"
            "process.exit(wasi.start(inst) ?? 0);\n",
            encoding="utf-8",
        )
        proc = subprocess.run(
            ["node", str(runner), str(wasm)], capture_output=True, text=True
        )
    output = proc.stdout.strip()
    print(output if output else "(no output)")
    if proc.returncode != 0 and not output:
        print(proc.stderr.strip()[-2000:])
    for line in output.splitlines():
        if line.startswith("PASS") or line.startswith("FAIL"):
            record(line[6:].strip() or "host check", line.startswith("PASS"))
    host_lines = [ln for ln in output.splitlines() if ln.startswith("HOST SUMMARY")]
    if host_lines:
        print(host_lines[-1])
    return proc.returncode == 0 and not any(
        line.startswith("FAIL") for line in output.splitlines())


if __name__ == "__main__":
    sys.exit(main())
